--Habitaciones disponibles en un rango de fechas
SELECT 
    hab.ID_Hotel,
    hot.Nombre AS Hotel,
    hab.Numero AS Numero_Habitacion,
    hab.Tipo,
    hab.Precio
FROM Habitacion hab
JOIN Hotel hot ON hab.ID_Hotel = hot.ID_Hotel
WHERE NOT EXISTS (
    SELECT 1 
    FROM RegistroHabitaciones rh
    JOIN Estadia est ON rh.ID_Estadia = est.ID_Estadia
    JOIN Reservacion res ON est.ID_Reservacion = res.ID_Reservacion
    WHERE rh.Numero = hab.Numero 
      AND rh.ID_Hotel = hab.ID_Hotel
      AND res.Estado IN ('PENDIENTE', 'COMPLETADA')
      -- Usamos estrictamente las fechas de Reservacion para bloquear rangos futuros
      AND res.Fecha_Inicio < '2026-07-15' -- <- Fecha Fin del rango deseado
      AND res.Fecha_Fin > '2026-07-01'   -- <- Fecha Inicio del rango deseado
);

--Huesped con mayor gasto histórico
SELECT 
    h.ID_Huesped,
    h.Nombre,
    h.Correo,
    COALESCE(SUM(f.Precio_total), 0) AS Gasto_Total_Historico
FROM Huesped h
JOIN Reservacion r ON h.ID_Huesped = r.ID_Huesped
JOIN Estadia e ON r.ID_Reservacion = e.ID_Reservacion
JOIN Factura f ON e.ID_Estadia = f.ID_Estadia
GROUP BY h.ID_Huesped, h.Nombre, h.Correo
ORDER BY Gasto_Total_Historico DESC;


--Servicios más consumidos por habitación
WITH ConteoServicios AS (
    SELECT 
        hab.Tipo AS Tipo_Habitacion,
        s.Nombre AS Nombre_Servicio,
        COUNT(hs.ID_HistorialServicios) AS Cantidad_Consumida,
        RANK() OVER (PARTITION BY hab.Tipo ORDER BY COUNT(hs.ID_HistorialServicios) DESC) AS Posicion
    FROM HistorialServicios hs
    JOIN Servicio s ON hs.ID_Servicio = s.ID_Servicio
    JOIN Estadia est ON hs.ID_Estadia = est.ID_Estadia
    JOIN RegistroHabitaciones rh ON est.ID_Estadia = rh.ID_Estadia
    JOIN Habitacion hab ON rh.Numero = hab.Numero AND rh.ID_Hotel = hab.ID_Hotel
    GROUP BY hab.Tipo, s.Nombre
)
SELECT 
    Tipo_Habitacion,
    Nombre_Servicio,
    Cantidad_Consumida
FROM ConteoServicios
WHERE Posicion = 1;
-- (Sección temporal de ajustes para reservaciones PENDIENTE removida)

--Tasa de ocupación mensual por tipo de habitación
SELECT 
    hab.Tipo AS Tipo_Habitacion,
    -- Días reales reservados dentro del mes evaluado
    SUM(
        CASE 
            WHEN res.Fecha_Fin < '2026-05-01' OR res.Fecha_Inicio > '2026-05-31' THEN 0
            ELSE (LEAST(res.Fecha_Fin, '2026-05-31'::DATE) - GREATEST(res.Fecha_Inicio, '2026-05-01'::DATE))
        END
    ) AS Dias_Ocupados,
    -- Capacidad total teórica del mes (Habitaciones de este tipo * 31 días)
    (COUNT(DISTINCT hab.Numero || '-' || hab.ID_Hotel) * 31) AS Dias_Disponibles,
    -- Porcentaje de ocupación final
    ROUND(
        (SUM(CASE 
                WHEN res.Fecha_Fin < '2026-05-01' OR res.Fecha_Inicio > '2026-05-31' THEN 0
                ELSE (LEAST(res.Fecha_Fin, '2026-05-31'::DATE) - GREATEST(res.Fecha_Inicio, '2026-05-01'::DATE))
             END)::NUMERIC 
         / 
        NULLIF((COUNT(DISTINCT hab.Numero || '-' || hab.ID_Hotel) * 31), 0)) * 100, 2
    ) AS Porcentaje_Ocupacion
FROM Habitacion hab
LEFT JOIN RegistroHabitaciones rh ON hab.Numero = rh.Numero AND hab.ID_Hotel = rh.ID_Hotel
LEFT JOIN Estadia est ON rh.ID_Estadia = est.ID_Estadia
LEFT JOIN Reservacion res ON est.ID_Reservacion = res.ID_Reservacion AND res.Estado IN ('PENDIENTE', 'COMPLETADA')
GROUP BY hab.Tipo;

--Ingresos totales por mes en el año en curso
SELECT 
    EXTRACT(MONTH FROM Fecha_factura) AS Numero_Mes,
    TO_CHAR(Fecha_factura, 'TMMonth') AS Nombre_Mes,
    SUM(Precio_total) AS Ingresos_Totales
FROM Factura
WHERE EXTRACT(YEAR FROM Fecha_factura) = 2026
GROUP BY EXTRACT(MONTH FROM Fecha_factura), TO_CHAR(Fecha_factura, 'TMMonth')
ORDER BY Numero_Mes;

